from collections import Counter


def _runs(values, background):
    runs = []
    i = 0
    while i < len(values):
        color = values[i]
        if color == background:
            i += 1
            continue
        j = i + 1
        while j < len(values) and values[j] == color:
            j += 1
        if j - i >= 2:
            runs.append((color, i, j - 1))
        i = j
    return runs


def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    candidates = []
    for orientation, edges in (
        ("tb", (grid[0], grid[-1])),
        ("lr", ([row[0] for row in grid], [row[-1] for row in grid])),
    ):
        a, b = (_runs(edge, background) for edge in edges)
        for ca, sa, ea in a:
            for cb, sb, eb in b:
                if ca == cb:
                    candidates.append((min(ea-sa+1, eb-sb+1), orientation, ca, (sa, ea), (sb, eb)))
    if not candidates:
        return out
    _, orientation, wall, seg_a, seg_b = max(candidates)
    if orientation == "tb":
        n, m = w, h
        edge_a, edge_b = 0, h - 1
    else:
        n, m = h, w
        edge_a, edge_b = 0, w - 1
    markers = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
               if grid[r][c] not in (background, wall)]
    for r, c, color in markers:
        pos = c if orientation == "tb" else r
        if seg_a[0] <= pos <= seg_a[1]:
            src, dst = seg_a, seg_b
            src_edge, dst_edge = edge_a, edge_b
        elif seg_b[0] <= pos <= seg_b[1]:
            src, dst = seg_b, seg_a
            src_edge, dst_edge = edge_b, edge_a
        else:
            continue
        mapped = dst[0] + (pos - src[0])
        # Draw from the point back to its supporting edge, preserving the wall.
        if orientation == "tb":
            for rr in range(min(r, src_edge) + 1, max(r, src_edge)):
                if out[rr][c] != wall:
                    out[rr][c] = color
            out[r][c] = 4
            # The translated line spans the grid perpendicular to the edge.
            for rr in range(h):
                if out[rr][mapped] != wall:
                    out[rr][mapped] = color
        else:
            for cc in range(min(c, src_edge) + 1, max(c, src_edge)):
                if out[r][cc] != wall:
                    out[r][cc] = color
            out[r][c] = 4
            for cc in range(w):
                if out[mapped][cc] != wall:
                    out[mapped][cc] = color
    return out
